// Sanity-checks `dist/` after a build.
// Astro can emit a silently empty page when a rehype plugin throws, so an
// automated check is the only reliable way to notice.
import fs from 'node:fs';
import path from 'node:path';

const DIST = 'dist';
const SOURCE_DIRS = {
  thinkoneering: 'docs/posts/ton',
  cv: 'docs/posts/cv',
  publications: 'docs/posts/publications',
};
// URLs the old mkdocs site served that are not generated by a page component.
const EXPECTED_FILES = [
  'robots.txt',
  'feed_rss_created.xml',
  'sitemap-index.xml',
  'autor/index.html',
];

/** Post pages only: `<category>/<file>/index.html`. */
function postUrls(root) {
  const out = [];
  for (const category of Object.keys(SOURCE_DIRS)) {
    const dir = path.join(root, category);
    if (!fs.existsSync(dir)) continue;
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      if (fs.existsSync(path.join(dir, entry.name, 'index.html'))) {
        out.push(`${category}/${entry.name}`);
      }
    }
  }
  return out.sort();
}

const failures = [];
const astroUrls = postUrls(DIST);

for (const file of EXPECTED_FILES) {
  if (!fs.existsSync(path.join(DIST, file))) failures.push(`missing ${file}`);
}

for (const url of astroUrls) {
  const [category, name] = url.split('/');
  const html = fs.readFileSync(path.join(DIST, url, 'index.html'), 'utf8');
  // `<main>` carries Astro's scoped-style attribute, so match it loosely.
  const start = html.search(/<main[\s>]/);
  const body = html.slice(start, html.indexOf('</main>'));
  const sourceBytes = fs.statSync(
    path.join(SOURCE_DIRS[category], `${name}.md`)
  ).size;

  if (!/<h1[\s>]/.test(body)) failures.push(`no <h1> in /${url}/`);
  // Catches content dropped by a throwing plugin; rendered HTML is normally
  // larger than its Markdown source, so a third is a generous floor.
  if (body.length < sourceBytes * 0.3) {
    failures.push(
      `content lost in /${url}/ (${body.length}B rendered from ${sourceBytes}B source)`
    );
  }
  if (/\{:[^}]*\}/.test(body)) failures.push(`leftover attr_list in /${url}/`);
  if (/\[-?@[a-zA-Z]/.test(body)) {
    failures.push(`unresolved citation in /${url}/`);
  }
  // The posts write `word[@key]`, which author-date would render as
  // `word(Author 2024)`. The remark shim inserts the space; this catches it
  // regressing.
  const text = body.replace(/<[^>]+>/g, '');
  const glued = text.match(/\S\((?:[A-Z][^()]{0,60})(?:1[6-9]|20)\d{2}[a-z]?\)/g);
  if (glued) {
    failures.push(`citation glued to preceding word in /${url}/: ${glued[0]}`);
  }
}

console.log(`checked ${astroUrls.length} post pages`);
if (failures.length) {
  for (const f of failures) console.error(`  FAIL  ${f}`);
  process.exit(1);
}
console.log('all checks passed');
